function maxPalindromesAfterOperations(words) {
  // Try every subset of words: it can be made of palindromes when its half-lengths fit in the available pairs.
  const freq = new Map();
  for (const ch of words.join('')) freq.set(ch, (freq.get(ch) || 0) + 1);
  const available = [...freq.values()].reduce((s, c) => s + (c - (c % 2)) / 2, 0);
  let best = 0;
  for (let mask = 0; mask < (1 << words.length); mask++) {
    let half = 0, size = 0;
    for (let i = 0; i < words.length; i++) if (mask & (1 << i)) { half += (words[i].length - (words[i].length % 2)) / 2; size++; }
    if (half <= available && size > best) best = size;
  }
  return best;
}

