function generate(rand, size) {
  const n = size === 'large' ? 300 + Math.floor(rand() * 400) : 1 + Math.floor(rand() * 7);
  const maxLength = size === 'large' ? 1 + Math.floor(rand() * 30) : 1 + Math.floor(rand() * 5);
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 1 + Math.floor(rand() * (size === 'large' ? 26 : 5)));
  // Favouring even lengths leaves fewer middle slots, so unmatched letters actually cost palindromes.
  const evenBias = rand();
  const words = [];
  for (let i = 0; i < n; i++) {
    let length = 1 + Math.floor(rand() * maxLength);
    if (rand() < evenBias && length % 2 === 1) length = length < 100 ? length + 1 : length - 1;
    let word = '';
    for (let j = 0; j < length; j++) word += alphabet[Math.floor(rand() * alphabet.length)];
    words.push(word);
  }
  return [words];
}
